CREATE FUNCTION jxc_supply_period_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP<>'INSERT' THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.biz_date); END IF; IF TG_OP<>'DELETE' THEN PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.biz_date); RETURN NEW; END IF; RETURN OLD; END $$;
CREATE TABLE md_supplier (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),code varchar(64) NOT NULL,name varchar(100) NOT NULL,settle_currency varchar(3) NOT NULL REFERENCES md_currency(code),located_country varchar(8) NOT NULL DEFAULT 'CN',payment_terms varchar(200) NOT NULL DEFAULT '',contact varchar(100) NOT NULL DEFAULT '',phone varchar(50) NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',bank_name varchar(200) NOT NULL DEFAULT '',account_name varchar(200) NOT NULL DEFAULT '',account_no_masked varchar(100) NOT NULL DEFAULT '',status varchar(16) NOT NULL DEFAULT 'ENABLED' CHECK(status IN ('ENABLED','DISABLED')),UNIQUE(country_id,code),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE md_logistics_provider (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),code varchar(64) NOT NULL,name varchar(100) NOT NULL,settle_currency varchar(3) NOT NULL REFERENCES md_currency(code),located_country varchar(8) NOT NULL DEFAULT 'CN',payment_terms varchar(200) NOT NULL DEFAULT '',contact varchar(100) NOT NULL DEFAULT '',phone varchar(50) NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',bank_name varchar(200) NOT NULL DEFAULT '',account_name varchar(200) NOT NULL DEFAULT '',account_no_masked varchar(100) NOT NULL DEFAULT '',status varchar(16) NOT NULL DEFAULT 'ENABLED' CHECK(status IN ('ENABLED','DISABLED')),UNIQUE(country_id,code),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE md_expense_item (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),code varchar(64) NOT NULL,name varchar(100) NOT NULL,cost_treatment varchar(16) NOT NULL CHECK(cost_treatment IN ('CAPITALIZE','EXPENSE')),fee_category varchar(64) NOT NULL DEFAULT '',status varchar(16) NOT NULL DEFAULT 'ENABLED' CHECK(status IN ('ENABLED','DISABLED')),UNIQUE(country_id,code),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE pur_order (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),supplier_id jxc_safe_id NOT NULL,source_country varchar(8) NOT NULL DEFAULT 'CN',currency varchar(3) NOT NULL REFERENCES md_currency(code),order_date date NOT NULL,expected_date date,payment_terms varchar(200) NOT NULL DEFAULT '',prepay_ratio numeric(9,6) NOT NULL DEFAULT 0 CHECK(prepay_ratio BETWEEN 0 AND 1),term_days integer NOT NULL DEFAULT 0 CHECK(term_days>=0),total_qty numeric(20,4) NOT NULL DEFAULT 0,total_amount numeric(20,4) NOT NULL DEFAULT 0,tax_amount numeric(20,4) NOT NULL DEFAULT 0,approval_instance_id jxc_safe_id,FOREIGN KEY(country_id,supplier_id) REFERENCES md_supplier(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER pur_order_period BEFORE INSERT OR UPDATE OR DELETE ON pur_order FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE pur_order_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),order_id jxc_safe_id NOT NULL,line_no integer NOT NULL,product_id jxc_safe_id NOT NULL,unit varchar(32) NOT NULL,factor numeric(20,6) NOT NULL CHECK(factor>0),qty numeric(20,4) NOT NULL CHECK(qty>0),base_qty numeric(20,4) NOT NULL CHECK(base_qty>0),unit_price numeric(20,4) NOT NULL CHECK(unit_price>=0),amount numeric(20,4) NOT NULL CHECK(amount>=0),tax_rate numeric(9,6) NOT NULL DEFAULT 0 CHECK(tax_rate BETWEEN 0 AND 1),delivery_date date,cancelled_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(cancelled_qty>=0),qualified_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(qualified_qty>=0),pending_inspect_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(pending_inspect_qty>=0),damaged_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(damaged_qty>=0),exported_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(exported_qty>=0),shipped_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(shipped_qty>=0),arrived_mx_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(arrived_mx_qty>=0),returned_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(returned_qty>=0),domestic_returned_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(domestic_returned_qty>=0),overseas_returned_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(overseas_returned_qty>=0),FOREIGN KEY(country_id,order_id) REFERENCES pur_order(country_id,id),UNIQUE(country_id,order_id,line_no),CHECK(cancelled_qty+qualified_qty+pending_inspect_qty<=base_qty),CHECK(arrived_mx_qty<=shipped_qty),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE pur_order_cancel (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,biz_date date NOT NULL,order_line_id jxc_safe_id NOT NULL,cancel_qty numeric(20,4) NOT NULL CHECK(cancel_qty>0),reason text NOT NULL,FOREIGN KEY(country_id,order_line_id) REFERENCES pur_order_line(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER pur_order_cancel_period BEFORE INSERT OR UPDATE OR DELETE ON pur_order_cancel FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE pur_domestic_receipt (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),order_id jxc_safe_id NOT NULL,supplier_id jxc_safe_id NOT NULL,receipt_date date NOT NULL,location varchar(200) NOT NULL DEFAULT '',FOREIGN KEY(country_id,order_id) REFERENCES pur_order(country_id,id),FOREIGN KEY(country_id,supplier_id) REFERENCES md_supplier(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER pur_domestic_receipt_period BEFORE INSERT OR UPDATE OR DELETE ON pur_domestic_receipt FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE pur_domestic_receipt_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),receipt_id jxc_safe_id NOT NULL,order_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,qualified_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(qualified_qty>=0),pending_inspect_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(pending_inspect_qty>=0),damaged_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(damaged_qty>=0),converted_qualified_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(converted_qualified_qty>=0),converted_damaged_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(converted_damaged_qty>=0),exported_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(exported_qty>=0),shipped_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(shipped_qty>=0),returned_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(returned_qty>=0),FOREIGN KEY(country_id,receipt_id) REFERENCES pur_domestic_receipt(country_id,id),FOREIGN KEY(country_id,order_line_id) REFERENCES pur_order_line(country_id,id),UNIQUE(country_id,receipt_id,order_line_id),CHECK(converted_qualified_qty+converted_damaged_qty<=pending_inspect_qty),CHECK(exported_qty+shipped_qty+returned_qty<=qualified_qty+converted_qualified_qty),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE pur_inspect_convert (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,biz_date date NOT NULL,receipt_line_id jxc_safe_id NOT NULL,to_qualified_qty numeric(20,4) NOT NULL CHECK(to_qualified_qty>=0),to_damaged_qty numeric(20,4) NOT NULL CHECK(to_damaged_qty>=0),remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,receipt_line_id) REFERENCES pur_domestic_receipt_line(country_id,id),CHECK(to_qualified_qty+to_damaged_qty>0),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER pur_inspect_convert_period BEFORE INSERT OR UPDATE OR DELETE ON pur_inspect_convert FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE pur_export_node (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),declaration_no varchar(100) NOT NULL,export_port varchar(100) NOT NULL DEFAULT '',export_date date NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER pur_export_node_period BEFORE INSERT OR UPDATE OR DELETE ON pur_export_node FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE pur_export_node_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),export_node_id jxc_safe_id NOT NULL,receipt_line_id jxc_safe_id NOT NULL,order_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,qty numeric(20,4) NOT NULL CHECK(qty>0),shipped_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(shipped_qty BETWEEN 0 AND qty),FOREIGN KEY(country_id,export_node_id) REFERENCES pur_export_node(country_id,id),FOREIGN KEY(country_id,receipt_line_id) REFERENCES pur_domestic_receipt_line(country_id,id),FOREIGN KEY(country_id,order_line_id) REFERENCES pur_order_line(country_id,id),UNIQUE(country_id,export_node_id,receipt_line_id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_shipment (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),carrier_id jxc_safe_id NOT NULL,dest_warehouse_id jxc_safe_id NOT NULL,transport_mode varchar(8) NOT NULL CHECK(transport_mode IN ('SEA','AIR')),origin_location varchar(200) NOT NULL DEFAULT '',bl_no varchar(100) NOT NULL DEFAULT '',vessel varchar(100) NOT NULL DEFAULT '',voyage varchar(100) NOT NULL DEFAULT '',awb_no varchar(100) NOT NULL DEFAULT '',flight_no varchar(100) NOT NULL DEFAULT '',current_container_no varchar(100) NOT NULL DEFAULT '',current_seal_no varchar(100) NOT NULL DEFAULT '',planned_etd timestamptz,planned_eta timestamptz,actual_etd timestamptz,actual_eta timestamptz,FOREIGN KEY(country_id,carrier_id) REFERENCES md_logistics_provider(country_id,id),FOREIGN KEY(country_id,dest_warehouse_id) REFERENCES org_warehouse(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_shipment_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_shipment FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_container (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,biz_date date NOT NULL,shipment_id jxc_safe_id NOT NULL,container_no varchar(100) NOT NULL,seal_no varchar(100) NOT NULL,active_from timestamptz NOT NULL DEFAULT clock_timestamp(),active_to timestamptz,FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_container_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_container FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_transship (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),shipment_id jxc_safe_id NOT NULL,old_container_no varchar(100) NOT NULL,new_container_no varchar(100) NOT NULL,new_seal_no varchar(100) NOT NULL,FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_transship_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_transship FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_transship_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),transship_id jxc_safe_id NOT NULL,shipment_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,in_container_qty numeric(20,4) NOT NULL CHECK(in_container_qty>=0),moved_qty numeric(20,4) NOT NULL CHECK(moved_qty>=0),diff_qty numeric(20,4) NOT NULL CHECK(diff_qty>=0),FOREIGN KEY(country_id,transship_id) REFERENCES lgs_transship(country_id,id),UNIQUE(country_id,transship_id,shipment_line_id),CHECK(in_container_qty=moved_qty+diff_qty),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_shipment_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),shipment_id jxc_safe_id NOT NULL,source_type varchar(32) NOT NULL CHECK(source_type IN ('EXPORT_NODE_LINE','DOMESTIC_RECEIPT_LINE')),source_line_id jxc_safe_id NOT NULL,po_id jxc_safe_id NOT NULL,po_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,base_qty numeric(20,4) NOT NULL CHECK(base_qty>0),shipped_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(shipped_qty BETWEEN 0 AND base_qty),intl_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(intl_qty>=0),pending_delivery_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(pending_delivery_qty>=0),on_hold_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(on_hold_qty>=0),delivering_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(delivering_qty>=0),received_good_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(received_good_qty>=0),received_frozen_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(received_frozen_qty>=0),discrepancy_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(discrepancy_qty>=0),FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),FOREIGN KEY(country_id,po_id) REFERENCES pur_order(country_id,id),FOREIGN KEY(country_id,po_line_id) REFERENCES pur_order_line(country_id,id),UNIQUE(country_id,shipment_id,source_type,source_line_id),CONSTRAINT lgs_line_conservation CHECK(shipped_qty=intl_qty+pending_delivery_qty+on_hold_qty+delivering_qty+received_good_qty+received_frozen_qty+discrepancy_qty),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_node (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,biz_date date NOT NULL,shipment_id jxc_safe_id NOT NULL,node_type varchar(32) NOT NULL,actual_at timestamptz NOT NULL DEFAULT clock_timestamp(),location varchar(200) NOT NULL DEFAULT '',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_node_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_node FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_hold (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),shipment_id jxc_safe_id NOT NULL,reason_code varchar(64) NOT NULL,park_location varchar(200) NOT NULL,owner_id jxc_safe_id NOT NULL REFERENCES sys_user(id),review_date date NOT NULL,FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_hold_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_hold FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_hold_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),hold_id jxc_safe_id NOT NULL,shipment_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,hold_qty numeric(20,4) NOT NULL CHECK(hold_qty>0),released_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(released_qty BETWEEN 0 AND hold_qty),FOREIGN KEY(country_id,hold_id) REFERENCES lgs_hold(country_id,id),FOREIGN KEY(country_id,shipment_line_id) REFERENCES lgs_shipment_line(country_id,id),UNIQUE(country_id,hold_id,shipment_line_id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_hold_release (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,biz_date date NOT NULL,hold_line_id jxc_safe_id NOT NULL,qty numeric(20,4) NOT NULL CHECK(qty>0),remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,hold_line_id) REFERENCES lgs_hold_line(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_hold_release_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_hold_release FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_delivery (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),shipment_id jxc_safe_id NOT NULL,dest_warehouse_id jxc_safe_id NOT NULL,vehicle varchar(100) NOT NULL DEFAULT '',driver varchar(100) NOT NULL DEFAULT '',planned_at timestamptz,dispatched_at timestamptz,FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),FOREIGN KEY(country_id,dest_warehouse_id) REFERENCES org_warehouse(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_delivery_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_delivery FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_delivery_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),delivery_id jxc_safe_id NOT NULL,shipment_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,po_line_id jxc_safe_id NOT NULL,dispatch_qty numeric(20,4) NOT NULL CHECK(dispatch_qty>0),received_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(received_qty BETWEEN 0 AND dispatch_qty),FOREIGN KEY(country_id,delivery_id) REFERENCES lgs_delivery(country_id,id),FOREIGN KEY(country_id,shipment_line_id) REFERENCES lgs_shipment_line(country_id,id),UNIQUE(country_id,delivery_id,shipment_line_id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_receipt (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),delivery_id jxc_safe_id NOT NULL,shipment_id jxc_safe_id NOT NULL,warehouse_id jxc_safe_id NOT NULL,FOREIGN KEY(country_id,delivery_id) REFERENCES lgs_delivery(country_id,id),FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),FOREIGN KEY(country_id,warehouse_id) REFERENCES org_warehouse(country_id,id),UNIQUE(country_id,delivery_id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_receipt_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_receipt FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_receipt_line (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),receipt_id jxc_safe_id NOT NULL,delivery_line_id jxc_safe_id NOT NULL,shipment_line_id jxc_safe_id NOT NULL,product_id jxc_safe_id NOT NULL,dispatch_qty numeric(20,4) NOT NULL CHECK(dispatch_qty>0),good_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(good_qty>=0),damaged_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(damaged_qty>=0),pending_inspect_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(pending_inspect_qty>=0),short_qty numeric(20,4) NOT NULL DEFAULT 0 CHECK(short_qty>=0),inv_batch_id jxc_safe_id,FOREIGN KEY(country_id,receipt_id) REFERENCES lgs_receipt(country_id,id),FOREIGN KEY(country_id,delivery_line_id) REFERENCES lgs_delivery_line(country_id,id),FOREIGN KEY(country_id,shipment_line_id) REFERENCES lgs_shipment_line(country_id,id),UNIQUE(country_id,receipt_id,delivery_line_id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TABLE lgs_discrepancy (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),shipment_id jxc_safe_id NOT NULL,shipment_line_id jxc_safe_id NOT NULL,receipt_line_id jxc_safe_id,product_id jxc_safe_id NOT NULL,qty numeric(20,4) NOT NULL CHECK(qty>0),discrepancy_type varchar(32) NOT NULL DEFAULT 'SHORT',resolution varchar(32),FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),FOREIGN KEY(country_id,shipment_line_id) REFERENCES lgs_shipment_line(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
CREATE TRIGGER lgs_discrepancy_period BEFORE INSERT OR UPDATE OR DELETE ON lgs_discrepancy FOR EACH ROW EXECUTE FUNCTION jxc_supply_period_guard();
CREATE TABLE lgs_fee (id jxc_safe_id PRIMARY KEY DEFAULT nextval('jxc_id_seq'),country_id jxc_safe_id NOT NULL REFERENCES sys_country(id),book_id jxc_safe_id NOT NULL,entity_id jxc_safe_id NOT NULL,biz_date date NOT NULL,doc_no varchar(64) NOT NULL,status varchar(32) NOT NULL DEFAULT 'DRAFT',remark text NOT NULL DEFAULT '',FOREIGN KEY(country_id,book_id) REFERENCES fin_book(country_id,id),FOREIGN KEY(country_id,entity_id) REFERENCES org_entity(country_id,id),UNIQUE(country_id,doc_no),shipment_id jxc_safe_id NOT NULL,ref_type varchar(32) NOT NULL,ref_id jxc_safe_id NOT NULL,carrier_id jxc_safe_id NOT NULL,expense_item_id jxc_safe_id NOT NULL,currency varchar(3) NOT NULL REFERENCES md_currency(code),amount numeric(20,4) NOT NULL CHECK(amount>0),estimate_flag varchar(8) NOT NULL CHECK(estimate_flag IN ('ESTIMATE','ACTUAL')),estimate_fee_id jxc_safe_id,actual_fee_id jxc_safe_id,cost_treatment varchar(16) NOT NULL CHECK(cost_treatment IN ('CAPITALIZE','EXPENSE')),cost_status varchar(24),fx_rate numeric(20,8),base_amount numeric(20,4),diff_amount numeric(20,4),cost_source jsonb NOT NULL DEFAULT '{}' CHECK(jxc_json_ids_safe(cost_source)),FOREIGN KEY(country_id,shipment_id) REFERENCES lgs_shipment(country_id,id),FOREIGN KEY(country_id,carrier_id) REFERENCES md_logistics_provider(country_id,id),FOREIGN KEY(country_id,estimate_fee_id) REFERENCES lgs_fee(country_id,id),FOREIGN KEY(country_id,actual_fee_id) REFERENCES lgs_fee(country_id,id),FOREIGN KEY(country_id,expense_item_id) REFERENCES md_expense_item(country_id,id),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by jxc_safe_id REFERENCES sys_user(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(country_id,id));
