CREATE FUNCTION pur_order_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_order WHERE country_id=OLD.country_id AND id=OLD.order_id; PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM pur_order WHERE country_id=NEW.country_id AND id=NEW.order_id; PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); RETURN NEW; END IF; RETURN OLD; END $$; CREATE TRIGGER pur_order_line_period BEFORE INSERT OR UPDATE OR DELETE ON pur_order_line FOR EACH ROW EXECUTE FUNCTION pur_order_line_guard();
