CREATE FUNCTION jxc_supply_source_identity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p record; source record; po record;
BEGIN
 IF TG_TABLE_NAME='pur_domestic_receipt_line' THEN
  SELECT r.order_id,l.order_id actual_order,l.product_id INTO p FROM pur_domestic_receipt r JOIN pur_order_line l ON l.country_id=r.country_id WHERE r.country_id=NEW.country_id AND r.id=NEW.receipt_id AND l.id=NEW.order_line_id;
  IF NOT FOUND OR p.order_id<>p.actual_order OR p.product_id<>NEW.product_id THEN RAISE EXCEPTION 'PUR_RECEIPT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='pur_export_node_line' THEN
  SELECT r.order_line_id,r.product_id,d.book_id,d.entity_id INTO source FROM pur_domestic_receipt_line r JOIN pur_domestic_receipt d ON d.country_id=r.country_id AND d.id=r.receipt_id WHERE r.country_id=NEW.country_id AND r.id=NEW.receipt_line_id;
  SELECT book_id,entity_id INTO p FROM pur_export_node WHERE country_id=NEW.country_id AND id=NEW.export_node_id;
  IF source IS NULL OR source.order_line_id<>NEW.order_line_id OR source.product_id<>NEW.product_id OR source.book_id<>p.book_id OR source.entity_id<>p.entity_id THEN RAISE EXCEPTION 'PUR_EXPORT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_shipment_line' THEN
  IF NEW.source_type='EXPORT_NODE_LINE' THEN SELECT l.order_line_id,l.product_id,d.book_id,d.entity_id INTO source FROM pur_export_node_line l JOIN pur_export_node d ON d.country_id=l.country_id AND d.id=l.export_node_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_line_id;
  ELSE SELECT l.order_line_id,l.product_id,d.book_id,d.entity_id INTO source FROM pur_domestic_receipt_line l JOIN pur_domestic_receipt d ON d.country_id=l.country_id AND d.id=l.receipt_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_line_id; END IF;
  SELECT book_id,entity_id INTO p FROM lgs_shipment WHERE country_id=NEW.country_id AND id=NEW.shipment_id;
  IF source IS NULL OR source.order_line_id<>NEW.po_line_id OR source.product_id<>NEW.product_id OR source.book_id<>p.book_id OR source.entity_id<>p.entity_id THEN RAISE EXCEPTION 'LGS_SHIPMENT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_delivery_line' THEN
  SELECT s.shipment_id,s.product_id,s.po_line_id INTO source FROM lgs_shipment_line s WHERE s.country_id=NEW.country_id AND s.id=NEW.shipment_line_id;
  SELECT shipment_id INTO p FROM lgs_delivery WHERE country_id=NEW.country_id AND id=NEW.delivery_id;
  IF source IS NULL OR source.shipment_id<>p.shipment_id OR source.product_id<>NEW.product_id OR source.po_line_id<>NEW.po_line_id THEN RAISE EXCEPTION 'LGS_DELIVERY_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_receipt_line' THEN
  SELECT l.delivery_id,l.shipment_line_id,l.product_id,l.dispatch_qty INTO source FROM lgs_delivery_line l WHERE l.country_id=NEW.country_id AND l.id=NEW.delivery_line_id;
  SELECT delivery_id,status INTO p FROM lgs_receipt WHERE country_id=NEW.country_id AND id=NEW.receipt_id;
  IF source IS NULL OR source.delivery_id<>p.delivery_id OR source.shipment_line_id<>NEW.shipment_line_id OR source.product_id<>NEW.product_id OR source.dispatch_qty<>NEW.dispatch_qty THEN RAISE EXCEPTION 'LGS_RECEIPT_SOURCE_MISMATCH'; END IF;
  IF p.status='CONFIRMED' AND NEW.good_qty+NEW.damaged_qty+NEW.pending_inspect_qty+NEW.short_qty<>NEW.dispatch_qty THEN RAISE EXCEPTION 'LGS_RECEIPT_QTY_MISMATCH'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER pur_receipt_identity BEFORE INSERT OR UPDATE ON pur_domestic_receipt_line FOR EACH ROW EXECUTE FUNCTION jxc_supply_source_identity();
CREATE TRIGGER pur_export_identity BEFORE INSERT OR UPDATE ON pur_export_node_line FOR EACH ROW EXECUTE FUNCTION jxc_supply_source_identity();
CREATE TRIGGER lgs_shipment_identity BEFORE INSERT OR UPDATE ON lgs_shipment_line FOR EACH ROW EXECUTE FUNCTION jxc_supply_source_identity();
CREATE TRIGGER lgs_delivery_identity BEFORE INSERT OR UPDATE ON lgs_delivery_line FOR EACH ROW EXECUTE FUNCTION jxc_supply_source_identity();
CREATE TRIGGER lgs_receipt_identity BEFORE INSERT OR UPDATE ON lgs_receipt_line FOR EACH ROW EXECUTE FUNCTION jxc_supply_source_identity();
CREATE FUNCTION jxc_receipt_confirm_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='CONFIRMED' AND EXISTS(SELECT 1 FROM lgs_receipt_line WHERE country_id=NEW.country_id AND receipt_id=NEW.id AND good_qty+damaged_qty+pending_inspect_qty+short_qty<>dispatch_qty) THEN RAISE EXCEPTION 'LGS_RECEIPT_QTY_MISMATCH'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lgs_receipt_quantities BEFORE UPDATE ON lgs_receipt FOR EACH ROW EXECUTE FUNCTION jxc_receipt_confirm_guard();

ALTER TABLE lgs_node ADD COLUMN supersedes_id jxc_safe_id,ADD COLUMN corrected_by_id jxc_safe_id,ADD CONSTRAINT lgs_node_supersedes FOREIGN KEY(country_id,supersedes_id) REFERENCES lgs_node(country_id,id),ADD CONSTRAINT lgs_node_corrected FOREIGN KEY(country_id,corrected_by_id) REFERENCES lgs_node(country_id,id);
CREATE FUNCTION jxc_lgs_node_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.country_id,NEW.book_id,NEW.biz_date,NEW.shipment_id,NEW.node_type,NEW.actual_at,NEW.location,NEW.remark,NEW.supersedes_id) IS DISTINCT FROM ROW(OLD.country_id,OLD.book_id,OLD.biz_date,OLD.shipment_id,OLD.node_type,OLD.actual_at,OLD.location,OLD.remark,OLD.supersedes_id) THEN RAISE EXCEPTION 'LGS_NODE_APPEND_ONLY'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lgs_node_immutable BEFORE UPDATE ON lgs_node FOR EACH ROW EXECUTE FUNCTION jxc_lgs_node_immutable();
ALTER TABLE lgs_transship_line ADD CONSTRAINT lgs_transship_source FOREIGN KEY(country_id,shipment_line_id) REFERENCES lgs_shipment_line(country_id,id);

ALTER TABLE md_supplier ADD COLUMN account_no_encrypted text;
ALTER TABLE md_logistics_provider ADD COLUMN account_no_encrypted text;

-- Source quantities are immutable facts; progress counters can be updated by new open-period commands.
CREATE OR REPLACE FUNCTION jxc_supply_period_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ignored text[];
BEGIN
 ignored:=CASE TG_TABLE_NAME WHEN 'pur_order' THEN ARRAY['status','version','approval_instance_id'] WHEN 'lgs_shipment' THEN ARRAY['status','version','actual_etd','actual_eta','current_container_no','current_seal_no'] WHEN 'lgs_delivery' THEN ARRAY['status','version','dispatched_at'] WHEN 'lgs_node' THEN ARRAY['version','corrected_by_id'] WHEN 'lgs_hold' THEN ARRAY['version','status'] WHEN 'lgs_discrepancy' THEN ARRAY['version','status','resolution','remark'] WHEN 'pur_domestic_receipt' THEN ARRAY['status','version'] WHEN 'pur_export_node' THEN ARRAY['status','version'] ELSE ARRAY['version'] END;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ignored)=(to_jsonb(OLD)-ignored) THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.biz_date); END IF;
 IF TG_OP<>'DELETE' THEN PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.biz_date); RETURN NEW; END IF; RETURN OLD;
END $$;
CREATE OR REPLACE FUNCTION pur_order_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND ROW(NEW.country_id,NEW.order_id,NEW.product_id,NEW.unit,NEW.base_unit,NEW.factor,NEW.qty,NEW.base_qty,NEW.unit_price,NEW.amount,NEW.tax_rate,NEW.delivery_date) IS NOT DISTINCT FROM ROW(OLD.country_id,OLD.order_id,OLD.product_id,OLD.unit,OLD.base_unit,OLD.factor,OLD.qty,OLD.base_qty,OLD.unit_price,OLD.amount,OLD.tax_rate,OLD.delivery_date) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_order WHERE country_id=OLD.country_id AND id=OLD.order_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM pur_order WHERE country_id=NEW.country_id AND id=NEW.order_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;
CREATE OR REPLACE FUNCTION pur_domestic_receipt_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND ROW(NEW.country_id,NEW.receipt_id,NEW.order_line_id,NEW.product_id,NEW.qualified_qty,NEW.pending_inspect_qty,NEW.damaged_qty)=ROW(OLD.country_id,OLD.receipt_id,OLD.order_line_id,OLD.product_id,OLD.qualified_qty,OLD.pending_inspect_qty,OLD.damaged_qty) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_domestic_receipt WHERE country_id=OLD.country_id AND id=OLD.receipt_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM pur_domestic_receipt WHERE country_id=NEW.country_id AND id=NEW.receipt_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;
CREATE OR REPLACE FUNCTION pur_export_node_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['shipped_qty','version'])=(to_jsonb(OLD)-ARRAY['shipped_qty','version']) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_export_node WHERE country_id=OLD.country_id AND id=OLD.export_node_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM pur_export_node WHERE country_id=NEW.country_id AND id=NEW.export_node_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;
CREATE OR REPLACE FUNCTION lgs_shipment_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND ROW(NEW.country_id,NEW.shipment_id,NEW.source_type,NEW.source_line_id,NEW.po_id,NEW.po_line_id,NEW.product_id,NEW.base_qty)=ROW(OLD.country_id,OLD.shipment_id,OLD.source_type,OLD.source_line_id,OLD.po_id,OLD.po_line_id,OLD.product_id,OLD.base_qty) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM lgs_shipment WHERE country_id=OLD.country_id AND id=OLD.shipment_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM lgs_shipment WHERE country_id=NEW.country_id AND id=NEW.shipment_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;
CREATE OR REPLACE FUNCTION lgs_delivery_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['received_qty','version'])=(to_jsonb(OLD)-ARRAY['received_qty','version']) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM lgs_delivery WHERE country_id=OLD.country_id AND id=OLD.delivery_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM lgs_delivery WHERE country_id=NEW.country_id AND id=NEW.delivery_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;

ALTER TABLE pur_order_line ADD COLUMN base_unit varchar(32) NOT NULL DEFAULT 'PCS';

CREATE OR REPLACE FUNCTION lgs_hold_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p record; BEGIN IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['released_qty','version'])=(to_jsonb(OLD)-ARRAY['released_qty','version']) THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM lgs_hold WHERE country_id=OLD.country_id AND id=OLD.hold_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date); END IF; IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM lgs_hold WHERE country_id=NEW.country_id AND id=NEW.hold_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;END $$;

ALTER TABLE lgs_fee ADD COLUMN incurred_location varchar(8) NOT NULL DEFAULT 'MX' CHECK(incurred_location IN ('CN','MX'));
